from scapy.all import rdpcap

def analyze_pcap(file_path):
    packets = rdpcap(file_path)
    summary = []

    for packet in packets:
        packet_info = {
            "protocol": packet.sprintf('%IP.proto%'),
            "src": packet.sprintf('%IP.src%'),
            "dst": packet.sprintf('%IP.dst%'),
            "length": len(packet)
        }

        summary.append(packet_info)

    return summary

if __name__ == "__main__":
    file_path = "/home/ctfplayer/ctf_files/constela.pcapng"
    result = analyze_pcap(file_path)
    with open("/home/ctfplayer/ctf_files/capture_summary.txt", "w") as output:
        for entry in result:
            output.write(f"Protocol: {entry['protocol']} Source: {entry['src']} Destination: {entry['dst']} Length: {entry['length']}\n")

from scapy.all import rdpcap

def extract_streams(pcap_file):
    packets = rdpcap(pcap_file)

    streams = []
    for packet in packets:
        if packet.haslayer('Raw'):
            try:
                data = bytes(packet['Raw'].load)
                streams.append(data)
            except Exception as e:
                continue

    return streams


def write_streams_to_files(streams, output_dir):
    from os import makedirs
    from os.path import join, exists

    if not exists(output_dir):
        makedirs(output_dir)

    for i, stream in enumerate(streams):
        with open(join(output_dir, f"stream_{i}.txt"), "wb") as f:
            f.write(stream)


if __name__ == "__main__":
    output_dir = "extracted_streams"
    pcap_file = "/home/ctfplayer/ctf_files/constela.pcapng"

    streams = extract_streams(pcap_file)
    write_streams_to_files(streams, output_dir)
